S=$0;read Q;read T;read K||K=0;python3 -c 'import sys,json as j,os,zlib as z,re,math as m,wave as W,struct as R;q,T,k,s=sys.argv[1:];t=max(8,min(60,int(T)));k="".join(c for c in k if c.isalnum())or"0";p=os.path;J=lambda x:j.dumps(x,separators=(",",":"));w=re.findall(r"\w+",q.lower())or["song"];qn=" ".join(w);e=p.getsize(s)if p.exists(s)else 0;y=(q+k+str(e)).encode();g=sum((b+1)*257**i for i,b in enumerate(y));Z=[[-2,-4,-6],[1+((g>>i)%997)/10 for i in(0,9,18)]];sc=([0,2,3,5,7,8,10],[0,2,4,5,7,9,11])[g&1];b=80+g%61;r=8000;rt=60/b;ro=180+g%90;ch=[0,5,3,4,0,5,6,4];me=[sc[(g>>(3*i))%7]+12*((g>>i)&1)for i in range(16)];ast=[b,ro,sc,ch,me];N=t*r;tw=2*m.pi;A=b"".join(R.pack("<h",int(12000*(m.sin(tw*ro*2**((ch[h]+me[a])/12)*x)*(x%rt<rt*.9)+.35*m.sin(tw*ro*2**(ch[h]/12)*x)+.25*((x%rt)<.04)*((g>>a)&3))))for n in range(N)for x in[n/r]for a in[int(x/rt)%16]for h in[int(x/(rt*4))%8]);tt="Anselm %s V%s"%(" ".join(x.title()for x in w[:8]),k);wv=tt+".wav";o=W.open(wv,"wb");o.setparams((1,2,r,N,"NONE",""));o.writeframes(A);o.close();ab=open(wv,"rb").read();G="C NL Z A P F X L V H".split();nl={"N":qn,"T":w,"M":"SONGAST","G":"B257"};Y=[(g+sum(me)+i*i)%997 for i in range((2<<min(t,10))-1)];tz=sum(y%2<1 for y in Y);nz=len(Y)-tz;op=list(min((y,i)for i,y in enumerate(Y)));C=[[G[0],qn],[G[1],nl],[G[2],Z],[G[3],ast],[G[4],op],[G[5],len(ab),z.crc32(ab)&0xffffffff],[G[6],wv],[G[7],tt],[G[8]],[G[9]]];v=int(j.loads(J(C))==C and tz+nz==len(Y) and op==list(min((y,i)for i,y in enumerate(Y)))and len(ab)>44);D={"P":"RMZANS2K","TM":"DAW-B257/AST/1","EQV":"SELF=FI+AI+AST","REC":"S>G>FI>AST>S","U":"TM*","BR":"PAR","FI":"VOC,LYR,T,K,H,M,R,MIX,MAST","AI":"NL,CODE,PCC,ZE","NLTM":nl,"SELF":e,"G":str(g),"Z":Z,"AST":ast,"CODE":C,"K":k,"ALL":len(Y),"TZ":tz,"NZ":nz,"OPT":op,"WAV":wv,"FILECERT":1,"TITLE":tt,"MODE":"song","V":v,"ANSCERT":v,"PCC":v,"ZE":v};open(tt+".clcert","w").write(J(D)+"\n");print(J(D))' "$Q" "$T" "$K" "$S"